//! Runtime for Rust generated by bendweave. Bend's native operations, bit for bit
//! as Bend's JS lane runs them (bend2/comp.ts), except Nat, which is unbounded
//! here (BigUint). U32 is u32; Char is its U32 code; Str is a list of Char codes.
//! Values are single-threaded (Rc), as a Bend computation is.
#![allow(clippy::all)]

use std::any::Any as StdAny;
use std::cell::RefCell;
use std::fmt;
use std::rc::Rc;

pub use num_bigint::BigUint as Nat;
use num_integer::Integer;
use num_traits::{ToPrimitive, Zero};

/// A runtime fail-stop: a state Bend's checker proves unreachable, or a resource limit.
#[cold]
pub fn panic(msg: &str) -> ! {
    panic!("bend: {}", msg)
}

pub fn absurd<T>() -> T {
    panic("runtime fail-stop")
}

// Any: a value whose Rust type the generator cannot name: one whose Bend type
// is computed from a value (a type family, like Vec(n)), or is unknown.
//
// Bend may spell one type two ways (Vec(1n) and Nat & Unit), so a value held
// as Any is in one dynamic form, whatever its static type was: a pair is a
// pair of Any, a closure takes and returns Any, everything else is itself.
// Dy converts a static type to and from that form.
// ===

pub type Any = Rc<dyn StdAny>;

pub trait Dy: Clone + 'static {
    fn up(self) -> Any;
    fn down(a: Any) -> Self;
}

fn raw_down<T: Clone + 'static>(x: Any) -> T {
    match x.downcast::<T>() {
        Ok(rc) => Rc::unwrap_or_clone(rc),
        Err(_) => panic(&format!("a value is not a {}", std::any::type_name::<T>())),
    }
}

pub fn up<T: Dy>(x: T) -> Any {
    x.up()
}

pub fn down<T: Dy>(x: Any) -> T {
    T::down(x)
}

macro_rules! dy_self {
    ($($t:ty),*) => { $(impl Dy for $t {
        fn up(self) -> Any { Rc::new(self) }
        fn down(a: Any) -> Self { raw_down(a) }
    })* };
}
dy_self!(u32, f32, bool, (), Nat, Str, Cmp);

impl Dy for Any {
    fn up(self) -> Any {
        self
    }
    fn down(a: Any) -> Self {
        a
    }
}

impl<A: Dy, B: Dy> Dy for (A, B) {
    fn up(self) -> Any {
        Rc::new((self.0.up(), self.1.up()))
    }
    fn down(a: Any) -> Self {
        let (x, y) = raw_down::<(Any, Any)>(a);
        (A::down(x), B::down(y))
    }
}

impl<A: Dy, B: Dy> Dy for Fun<A, B> {
    fn up(self) -> Any {
        Rc::new(Fun::new(move |x: Any| self.call(A::down(x)).up()))
    }
    fn down(a: Any) -> Self {
        let f = raw_down::<Fun<Any, Any>>(a);
        Fun::new(move |x: A| B::down(f.call(x.up())))
    }
}

impl<T: Clone + 'static> Dy for Arr<T> {
    fn up(self) -> Any {
        Rc::new(self)
    }
    fn down(a: Any) -> Self {
        raw_down(a)
    }
}

/// A generated datatype. Held as Any it is itself: a datatype's own type
/// arguments are not converted, so one that reaches an Any under two
/// spellings of its arguments fail-stops ("a value is not a ...").
pub trait Node: Clone + 'static {}

impl<T: Node> Dy for Rc<T> {
    fn up(self) -> Any {
        Rc::new(self)
    }
    fn down(a: Any) -> Self {
        raw_down(a)
    }
}

// Fun: a Bend closure. Bend closures are affine: each is called at most once.
// ===

pub struct Fun<A, B>(Rc<RefCell<Option<Box<dyn FnOnce(A) -> B>>>>);

impl<A, B> Fun<A, B> {
    pub fn new(f: impl FnOnce(A) -> B + 'static) -> Self {
        Fun(Rc::new(RefCell::new(Some(Box::new(f)))))
    }
    pub fn call(self, a: A) -> B {
        let f = self.0.borrow_mut().take().unwrap_or_else(|| panic("a closure called twice"));
        f(a)
    }
}

impl<A, B> Clone for Fun<A, B> {
    fn clone(&self) -> Self {
        Fun(self.0.clone())
    }
}

impl<A, B> fmt::Debug for Fun<A, B> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<fn>")
    }
}

// Cmp
// ===

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Cmp {
    LT,
    EQ,
    GT,
}

pub fn cmp(o: std::cmp::Ordering) -> Cmp {
    match o {
        std::cmp::Ordering::Less => Cmp::LT,
        std::cmp::Ordering::Equal => Cmp::EQ,
        std::cmp::Ordering::Greater => Cmp::GT,
    }
}

pub fn opt<M>(v: Option<f32>, none: impl FnOnce() -> M, some: impl FnOnce(f32) -> M) -> M {
    match v {
        None => none(),
        Some(x) => some(x),
    }
}

// U32
// ===

pub fn u32_div(a: u32, b: u32) -> u32 {
    if b == 0 { 0 } else { a / b }
}

pub fn u32_mod(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { a % b }
}

pub fn u32_shln(a: u32, n: Nat) -> u32 {
    match n.to_u32() {
        Some(k) if k < 32 => a << k,
        _ => 0,
    }
}

pub fn u32_shrn(a: u32, n: Nat) -> u32 {
    match n.to_u32() {
        Some(k) if k < 32 => a >> k,
        _ => 0,
    }
}

// Nat
// ===

pub fn nat(n: u64) -> Nat {
    Nat::from(n)
}

pub fn nat_eq(a: &Nat, n: u64) -> bool {
    a.to_u64() == Some(n)
}

pub fn nat_low32(a: Nat) -> u32 {
    a.iter_u32_digits().next().unwrap_or(0)
}

pub fn nat_sub(a: Nat, b: Nat) -> Nat {
    if a < b { Nat::zero() } else { a - b }
}

pub fn nat_divmod(a: Nat, b: Nat) -> (Nat, Nat) {
    if b.is_zero() { (Nat::zero(), a) } else { a.div_rem(&b) }
}

/// The Nat, correctly rounded to the nearest f32 (ties to even).
pub fn nat_to_f32(a: Nat) -> f32 {
    let bits = a.bits();
    if bits <= 24 {
        return a.to_u32().unwrap() as f32;
    }
    if bits > 128 {
        return f32::INFINITY;
    }
    let shift = bits - 25; // keep 25 bits: 24 of mantissa and a round bit
    let top = (&a >> shift).to_u32().unwrap();
    let sticky = a.trailing_zeros().map_or(false, |z| z < shift);
    let mut m = top >> 1;
    let round = top & 1 == 1;
    if round && (sticky || m & 1 == 1) {
        m += 1;
    }
    let v = m as f64 * 2f64.powi((shift + 1) as i32);
    if v >= 2f64.powi(128) { f32::INFINITY } else { v as f32 }
}

// F32
// ===
// + - * / % sqrt floor ceil trunc abs are exact IEEE single operations; the
// transcendental ones go through f64 as the JS lane does (Math.fround(Math.f(x)))
// and may differ from another lane's libm in the last bit (Bend's WONTFIX).

macro_rules! f64_via {
    ($($n:ident),*) => { $(pub fn $n(x: f32) -> f32 { (x as f64).$n() as f32 })* };
}
pub mod f {
    f64_via!(exp, ln, log2, log10, sin, cos, tan, asin, acos, atan, sinh, cosh, tanh);
    pub fn atan2(y: f32, x: f32) -> f32 {
        (y as f64).atan2(x as f64) as f32
    }
    pub fn pow(a: f32, b: f32) -> f32 {
        if a == 1.0 || (a == -1.0 && b.is_infinite()) { 1.0 } else { (a as f64).powf(b as f64) as f32 }
    }
}

pub fn f32_to_u32(x: f32) -> u32 {
    if x >= 1.0 && x < 4294967296.0 { x.floor() as u32 } else { 0 }
}

/// F32.read: the float the text spells, correctly rounded, or None.
pub fn f32_read(s: Str) -> Option<f32> {
    let t: String = s.to_string();
    let w = t.trim_start_matches(|c| matches!(c, '\t' | '\n' | '\u{b}' | '\u{c}' | '\r' | ' '));
    let (neg, body) = match w.as_bytes().first() {
        Some(b'-') => (true, &w[1..]),
        Some(b'+') => (false, &w[1..]),
        _ => (false, w),
    };
    let low = body.to_ascii_lowercase();
    let v = if low == "nan" {
        f32::NAN
    } else if low == "inf" || low == "infinity" {
        f32::INFINITY
    } else {
        let b = low.as_bytes();
        let mut i = 0;
        let digits = |i: &mut usize| {
            let s = *i;
            while *i < b.len() && b[*i].is_ascii_digit() {
                *i += 1;
            }
            *i - s
        };
        let int = digits(&mut i);
        let mut frac = 0;
        if i < b.len() && b[i] == b'.' {
            i += 1;
            frac = digits(&mut i);
        }
        if int + frac == 0 || (int == 0 && frac == 0) {
            return None;
        }
        if i < b.len() && b[i] == b'e' {
            i += 1;
            if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
                i += 1;
            }
            if digits(&mut i) == 0 {
                return None;
            }
        }
        if i != b.len() {
            return None;
        }
        // Rust's f32 parse is correctly rounded from the decimal
        low.parse::<f32>().ok()?
    };
    Some(if neg { -v } else { v })
}

/// F32.show: the shortest decimal that reads back to x, in JS's Number format.
pub fn f32_show(x: f32) -> Str {
    Str::from(f32_show_text(x).as_str())
}

pub fn f32_show_text(x: f32) -> String {
    if x.is_nan() {
        return "nan".into();
    }
    if x.is_infinite() {
        return if x > 0.0 { "inf".into() } else { "-inf".into() };
    }
    if x == 0.0 {
        return if x.is_sign_negative() { "-0".into() } else { "0".into() };
    }
    // JS's loop: toExponential(p - 1) for p = 1..9 (half up on the exact
    // value) until the digits read back to x
    let (digits, n) = shortest(x);
    let sign = if x < 0.0 { "-" } else { "" };
    let k = digits.len() as i32;
    let out = if k <= n && n <= 21 {
        format!("{}{}", digits, "0".repeat((n - k) as usize))
    } else if 0 < n && n <= 21 {
        format!("{}.{}", &digits[..n as usize], &digits[n as usize..])
    } else if -6 < n && n <= 0 {
        format!("0.{}{}", "0".repeat((-n) as usize), digits)
    } else {
        let e = n - 1;
        let rest = if k > 1 { format!(".{}", &digits[1..]) } else { String::new() };
        format!("{}{}e{}{}", &digits[..1], rest, if e < 0 { "-" } else { "+" }, e.abs())
    };
    format!("{}{}", sign, out)
}

// the digits and the point position n (|x| = 0.digits * 10^n), shortest first,
// found as JS's lane finds them: p = 1..9 significant digits, half up
fn shortest(x: f32) -> (String, i32) {
    let (ds0, n0) = exact_digits((x as f64).abs());
    for p in 1..=9usize {
        let (ds, e) = round_half_up(&ds0, n0, p);
        let back: f32 = format!("{}e{}", ds, e - (p as i32 - 1)).parse().unwrap();
        if back == x.abs() {
            let t = ds.trim_end_matches('0');
            return ((if t.is_empty() { "0" } else { t }).to_string(), e + 1);
        }
    }
    let (ds, e) = round_half_up(&ds0, n0, 9);
    (ds.trim_end_matches('0').to_string(), e + 1)
}

// the exact decimal digits of a finite positive f64, and its point position
fn exact_digits(a: f64) -> (String, i32) {
    let bits = a.to_bits();
    let exp = ((bits >> 52) & 0x7FF) as i32;
    let man = bits & ((1u64 << 52) - 1);
    let (m, e2) = if exp == 0 { (man, -1074) } else { (man | (1u64 << 52), exp - 1075) };
    let v = Nat::from(m);
    let (num, scale) = if e2 >= 0 { (v << (e2 as u64), 0) } else { (v * Nat::from(5u32).pow((-e2) as u32), -e2) };
    let s = num.to_string();
    let n = s.len() as i32 - scale;
    (s.trim_end_matches('0').to_string(), n)
}

// round the digits (0.ds * 10^n) to p significant digits, half up
fn round_half_up(ds: &str, n: i32, p: usize) -> (String, i32) {
    let mut d: Vec<u8> = ds.bytes().map(|b| b - b'0').collect();
    if d.len() <= p {
        d.resize(p, 0);
        return (d.iter().map(|x| (x + b'0') as char).collect(), n - 1);
    }
    let up = d[p] >= 5;
    d.truncate(p);
    let mut n = n;
    if up {
        let mut i = p;
        loop {
            if i == 0 {
                d.insert(0, 1);
                d.truncate(p);
                n += 1;
                break;
            }
            i -= 1;
            if d[i] == 9 {
                d[i] = 0;
            } else {
                d[i] += 1;
                break;
            }
        }
    }
    (d.iter().map(|x| (x + b'0') as char).collect(), n - 1)
}

// Str: Bend's String, a list of Char codes (any U32). Taking the head or tail
// and putting a Char in front are O(1): a value is a view of a shared buffer
// that holds the Chars last first, and a cons writes past the view when
// nothing else has.
// ===

#[derive(Clone)]
pub struct Str {
    buf: Rc<RefCell<Vec<u32>>>,
    len: usize,
}

impl Str {
    fn own(v: Vec<u32>) -> Str {
        let len = v.len();
        Str { buf: Rc::new(RefCell::new(v)), len }
    }
    pub fn empty() -> Str {
        Str::own(Vec::new())
    }
    /// The Chars with these codes, first to last.
    pub fn from_codes(cs: &[u32]) -> Str {
        Str::own(cs.iter().rev().copied().collect())
    }
    /// The codes, first to last.
    pub fn codes(&self) -> Vec<u32> {
        self.buf.borrow()[..self.len].iter().rev().copied().collect()
    }
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
    pub fn len(&self) -> usize {
        self.len
    }
    // this string with room to grow in place: itself when it ends where its
    // buffer does, else a copy
    fn grow(self) -> Str {
        if self.buf.borrow().len() == self.len {
            self
        } else {
            let v = self.buf.borrow()[..self.len].to_vec();
            Str::own(v)
        }
    }
    pub fn cons(c: u32, s: Str) -> Str {
        let s = s.grow();
        s.buf.borrow_mut().push(c);
        Str { len: s.len + 1, buf: s.buf }
    }
    /// The first Char's code and the rest; the string is not empty.
    pub fn uncons(self) -> (u32, Str) {
        let c = self.buf.borrow()[self.len - 1];
        (c, Str { len: self.len - 1, buf: self.buf })
    }
    /// self followed by b.
    pub fn append(self, b: Str) -> Str {
        if self.len == 0 {
            return b;
        }
        let xs = self.buf.borrow()[..self.len].to_vec();
        let b = b.grow();
        b.buf.borrow_mut().extend_from_slice(&xs);
        Str { len: b.len + xs.len(), buf: b.buf }
    }
    pub fn contains(self, p: Str) -> bool {
        let (s, p) = (self.codes(), p.codes());
        p.is_empty() || s.windows(p.len()).any(|w| w == &p[..])
    }
    pub fn len_nat(self) -> Nat {
        Nat::from(self.len)
    }
}

impl From<&str> for Str {
    fn from(s: &str) -> Str {
        Str::own(s.chars().rev().map(|c| c as u32).collect())
    }
}

/// A Char past the Unicode scalars shows as U+FFFD, as Bend's lanes print it.
impl fmt::Display for Str {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        for c in self.codes() {
            write!(f, "{}", char::from_u32(c).unwrap_or('\u{FFFD}'))?;
        }
        Ok(())
    }
}

impl fmt::Debug for Str {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}", self.to_string())
    }
}

impl PartialEq for Str {
    fn eq(&self, o: &Str) -> bool {
        self.len == o.len && self.buf.borrow()[..self.len] == o.buf.borrow()[..o.len]
    }
}

// Arr: Bend's Array<T>, 2^d slots, indexes wrap. A Bend array has one owner
// (it is affine), so a write happens in place.
// ===

#[derive(Clone, Debug, PartialEq)]
pub struct Arr<T>(pub Vec<T>);

impl<T: Clone> Arr<T> {
    pub fn make(d: Nat, v: T) -> Arr<T> {
        match d.to_u32() {
            Some(k) if k <= 40 => Arr(vec![v; 1usize << k]),
            _ => panic("an array past depth 40"),
        }
    }
    pub fn leaf(v: T) -> Arr<T> {
        Arr(vec![v])
    }
    pub fn node(mut a: Arr<T>, b: Arr<T>) -> Arr<T> {
        if a.0.len() != b.0.len() {
            panic("runtime fail-stop");
        }
        a.0.extend(b.0);
        a
    }
    pub fn len(&self) -> usize {
        self.0.len()
    }
    pub fn into_leaf(self) -> T {
        self.0.into_iter().next().unwrap()
    }
    pub fn split(mut self) -> (Arr<T>, Arr<T>) {
        let hi = self.0.split_off(self.0.len() >> 1);
        (self, Arr(hi))
    }
    fn at(&self, i: u32) -> usize {
        (i as usize) % self.0.len()
    }
    pub fn set(mut self, i: u32, v: T) -> Arr<T> {
        let j = self.at(i);
        self.0[j] = v;
        self
    }
    pub fn get_t(self, i: u32) -> (Arr<T>, T) {
        let v = self.0[self.at(i)].clone();
        (self, v)
    }
    pub fn swap_t(mut self, i: u32, v: T) -> (Arr<T>, T) {
        let j = self.at(i);
        let old = std::mem::replace(&mut self.0[j], v);
        (self, old)
    }
    pub fn size_t(self) -> (Arr<T>, u32) {
        let n = self.0.len() as u32;
        (self, n)
    }
    pub fn clone_t(self) -> (Arr<T>, Arr<T>) {
        let c = self.clone();
        (self, c)
    }
}

/// Runs f on a thread with a big stack: generated code recurses as Bend does.
pub fn with_stack<T: Send + 'static>(f: impl FnOnce() -> T + Send + 'static) -> T {
    std::thread::Builder::new().stack_size(1 << 30).spawn(f).unwrap().join().unwrap()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn big(bits: u64) -> Nat {
        Nat::from(1u32) << bits
    }

    #[test]
    fn u32_ops() {
        assert_eq!(u32_div(7, 0), 0);
        assert_eq!(u32_mod(7, 0), 7);
        assert_eq!(u32_div(u32::MAX, 2), 0x7FFF_FFFF);
        assert_eq!(u32_shln(1, nat(31)), 1 << 31);
        assert_eq!(u32_shln(u32::MAX, nat(32)), 0);
        assert_eq!(u32_shln(u32::MAX, big(70)), 0);
        assert_eq!(u32_shrn(u32::MAX, nat(31)), 1);
        assert_eq!(u32_shrn(u32::MAX, big(70)), 0);
    }

    #[test]
    fn nat_ops() {
        let a = big(100);
        assert_eq!(nat_sub(nat(3), a.clone()), nat(0));
        assert_eq!(nat_sub(a.clone(), nat(3)) + nat(3), a);
        assert_eq!(nat_divmod(a.clone(), nat(0)), (nat(0), a.clone()));
        let (q, r) = nat_divmod(a.clone(), nat(7));
        assert_eq!(q * nat(7) + r, a);
        assert_eq!(nat_low32(a.clone() + nat(12345)), 12345);
        assert_eq!(nat_low32(big(32) - nat(1)), u32::MAX);
        assert!(nat_eq(&nat(5), 5) && !nat_eq(&a, 5));
    }

    // an integer to f32, round to nearest even: Rust's own cast is the reference
    #[test]
    fn nat_f32() {
        let mut x: u64 = 0x9E37_79B9_7F4A_7C15;
        for _ in 0..200_000 {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            let v = x >> (x % 64);
            assert_eq!(nat_to_f32(nat(v)).to_bits(), (v as f32).to_bits(), "{}", v);
            let w = (v as u128) << (x % 60);
            assert_eq!(nat_to_f32(Nat::from(w)).to_bits(), (w as f32).to_bits(), "{}", w);
        }
        for v in [0u64, 1, 16777215, 16777216, 16777217, 16777218, 16777219, u64::MAX] {
            assert_eq!(nat_to_f32(nat(v)).to_bits(), (v as f32).to_bits());
        }
        assert_eq!(nat_to_f32(big(127)), 2f32.powi(127));
        assert_eq!(nat_to_f32(big(128)), f32::INFINITY);
        assert_eq!(nat_to_f32(big(128) - big(104)), f32::MAX);
        assert_eq!(nat_to_f32(big(128) - big(103)), f32::INFINITY); // the tie rounds up
        assert_eq!(nat_to_f32(big(128) - big(103) - nat(1)), f32::MAX);
        assert_eq!(nat_to_f32(big(500)), f32::INFINITY);
    }

    #[test]
    fn f32_text() {
        for (x, s) in [(0.1f32, "0.1"), (16777216.0, "16777216"), (1e21, "1e+21"), (1.5e22, "1.5e+22"),
            (1e-7, "1e-7"), (0.000001, "0.000001"), (f32::MAX, "3.4028235e+38"), (-0.0, "-0"), (-2.5, "-2.5"),
            (f32::INFINITY, "inf"), (f32::NEG_INFINITY, "-inf"), (1.0 / 3.0, "0.33333334"), (f32::MIN_POSITIVE, "1.1754944e-38")] {
            assert_eq!(f32_show_text(x), s);
            assert_eq!(f32_read(Str::from(s)).map(f32::to_bits), Some(x.to_bits()), "{}", s);
        }
        assert_eq!(f32_show_text(f32::NAN), "nan");
        assert!(f32_read(Str::from("NaN")).unwrap().is_nan());
        for s in ["", ".", "e5", "1e", "1e+", "1x", " 1 ", "0x10", "--1", "1.5.2", "infin"] {
            assert_eq!(f32_read(Str::from(s)), None, "{:?}", s);
        }
        for (s, v) in [(" \t1.5", 1.5f32), ("+.5", 0.5), ("5.", 5.0), ("1E2", 100.0), ("-Infinity", f32::NEG_INFINITY), ("1e400", f32::INFINITY)] {
            assert_eq!(f32_read(Str::from(s)), Some(v), "{:?}", s);
        }
        // every f32 reads back from its text
        let mut x: u32 = 0x1234_5678;
        for _ in 0..200_000 {
            x ^= x << 13;
            x ^= x >> 17;
            x ^= x << 5;
            let v = f32::from_bits(x);
            if v.is_finite() {
                assert_eq!(f32_read(f32_show(v)).map(f32::to_bits), Some(x), "{}", v);
            }
        }
        assert_eq!(f32_to_u32(4e9), 4_000_000_000);
        assert_eq!(f32_to_u32(-3.0), 0);
        assert_eq!(f32_to_u32(5e9), 0);
        assert_eq!(f32_to_u32(0.99), 0);
        assert_eq!(f32_to_u32(f32::NAN), 0);
    }

    #[test]
    fn strings() {
        let s = Str::from("abc");
        assert_eq!(s.codes(), vec![97, 98, 99]);
        // two conses on one string: the second may not write over the first
        let a = Str::cons(120, s.clone());
        let b = Str::cons(121, s.clone());
        assert_eq!((a.to_string(), b.to_string(), s.to_string()), ("xabc".into(), "yabc".into(), "abc".into()));
        let (h, t) = a.clone().uncons();
        assert_eq!((h, t.to_string()), (120, "abc".to_string()));
        let c = Str::cons(122, t.clone());
        assert_eq!((c.to_string(), a.to_string()), ("zabc".into(), "xabc".into()));
        assert_eq!(s.clone().append(s.clone()).to_string(), "abcabc");
        assert_eq!(s.to_string(), "abc");
        assert_eq!(Str::empty().append(s.clone()), s);
        assert_eq!(s.clone().append(Str::empty()), s);
        assert!(s.clone().contains(Str::from("bc")) && s.clone().contains(Str::empty()) && !s.clone().contains(Str::from("cb")));
        assert_eq!(Str::from_codes(&[0xD800, 65, 0x110000]).to_string(), "\u{FFFD}A\u{FFFD}");
        assert_eq!(Str::from("世界😀").len_nat(), nat(3));
        let mut l = Str::empty();
        for i in 0..200_000u32 {
            l = Str::cons(i, l);
        }
        let mut n = 0u64;
        while !l.is_empty() {
            let (h, t) = l.uncons();
            n += h as u64;
            l = t;
        }
        assert_eq!(n, 199_999 * 200_000 / 2);
    }

    #[test]
    fn dynamic() {
        // one type, two spellings: (Nat, (Nat, ())) and (Nat, Any)
        let v: Any = up((nat(1), (nat(2), ())));
        let (a, rest): (Nat, Any) = down(v);
        let (b, end): (Nat, Any) = down(rest);
        let _: () = down(end);
        assert_eq!((a, b), (nat(1), nat(2)));
        let w: Any = up((nat(1), up((nat(2), up(())))));
        let (_, (c, ())): (Nat, (Nat, ())) = down(w);
        assert_eq!(c, nat(2));
        let f: Any = up(Fun::new(|x: u32| (x, x + 1)));
        let g: Fun<Any, (u32, Any)> = down(f);
        let (p, q) = g.call(up(4u32));
        assert_eq!((p, down::<u32>(q)), (4, 5));
    }

    #[test]
    fn arrays() {
        let a = Arr::make(nat(3), 5u32).set(13, 7);
        assert_eq!(a.clone().get_t(5).1, 7);
        assert_eq!(a.clone().get_t(4).1, 5);
        let (a, old) = a.swap_t(21, 9);
        assert_eq!((old, a.clone().get_t(5).1, a.clone().size_t().1), (7, 9, 8));
        let (lo, hi) = a.split();
        assert_eq!(Arr::node(lo, hi).len(), 8);
    }

    #[test]
    #[should_panic(expected = "called twice")]
    fn closure_once() {
        let f = Fun::new(|x: u32| x + 1);
        let g = f.clone();
        assert_eq!(f.call(1), 2);
        g.call(1);
    }
}
